ate.view','Ver Security Gate'),('security.gate.evaluate','Evaluar Security Gate'),('security.config.view','Ver configuración no secreta'),('security.config.manage','Gestionar configuración de seguridad'),('security.report.view','Ver reportes de seguridad'),('security.report.export','Exportar reportes restringidos')
