insert into public.role_permissions(role,permission_code)select r.role,p.code from(values('GERENTE_GENERAL'),('SECURITY_ADMIN'))r(role)cross join public.app_permissions p where p.code like'security.%'or p.code like'identity.%'or p.code like'mfa.%'or p.code like'role.%'or p.code like'permission.%'or p.code like'session.%'or p.code like'device.%'or p.code like'jit.%'or p.code like'vault.%'or p.code like'incident.%'or p.code like'vulnerability.%'or p.code like'rls.%'or p.code like'privacy.%'or p.code like'dlp.%'or p.code like'vendor_security.%'or p.code like'backup.%'or p.code like'compliance.%'on conflict do nothing;
insert into public.role_permissions(role,permission_code)values('JEFE_DESARROLLO','vault.metadata.view'),('JEFE_DESARROLLO','jit.request'),('TECH_LEAD','vault.metadata.view'),('TECH_LEAD','jit.request'),('PROGRAMADOR','vault.metadata.view'),('PROGRAMADOR','jit.request'),('RRHH','privacy.subject_request.view'),('FINANZAS','security.dashboard.view')on conflict do nothing;

do $$declare t text;begin foreach t in array array['security_events','security_incidents','security_incident_events','security_session_metadata','registered_devices','access_requests','access_grants','security_vulnerabilities','production_security_gates']loop if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime'and schemaname='public'and tablename=t)then execute format('alter publication supabase_realtime add table public.%I',t);end if;end loop;end$$;

commit;
